/* Quantum Rose Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="quantum-rose-light"] {
  --background: hsl(328.01 100% 97.14%);
  --foreground: hsl(325.46 77.85% 32.1%);
  --card: hsl(322.52 69.76% 97.9%);
  --card-foreground: hsl(325.46 77.85% 32.1%);
  --popover: hsl(322.52 69.76% 97.9%);
  --popover-foreground: hsl(325.46 77.85% 32.1%);
  --primary: hsl(329.4 91.53% 46.98%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(300 95.15% 91.57%);
  --secondary-foreground: hsl(325.46 77.85% 32.1%);
  --muted: hsl(327.8 99.9% 94.23%);
  --muted-foreground: hsl(329.16 48.49% 50.17%);
  --accent: hsl(327.18 99.68% 88.19%);
  --accent-foreground: hsl(325.46 77.85% 32.1%);
  --destructive: hsl(340.79 61.52% 51.59%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(326.93 94.54% 89.09%);
  --input: hsl(300 95.15% 91.57%);
  --ring: hsl(329.4 91.53% 46.98%);
  --chart-1: hsl(329.4 91.53% 46.98%);
  --chart-2: hsl(322.57 49.44% 53.52%);
  --chart-3: hsl(277.33 33.08% 56.02%);
  --chart-4: hsl(241.71 38.12% 59.19%);
  --chart-5: hsl(225.78 99.97% 68.61%);
  --radius: 0.5rem;
  --sidebar: hsl(330.08 76.73% 95.94%);
  --sidebar-foreground: hsl(325.46 77.85% 32.1%);
  --sidebar-primary: hsl(329.4 91.53% 46.98%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(327.18 99.68% 88.19%);
  --sidebar-accent-foreground: hsl(325.46 77.85% 32.1%);
  --sidebar-border: hsl(326.61 84.8% 92.97%);
  --sidebar-ring: hsl(329.4 91.53% 46.98%);
  --font-sans: Poppins, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Space Mono, monospace;
  --shadow-color: hsl(330 70% 30% / 0.12);
  --shadow-opacity: 0.18;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
  --shadow-xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
  --shadow-sm:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 1px 2px -1px hsl(330 70% 30% / 0.18);
  --shadow:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 1px 2px -1px hsl(330 70% 30% / 0.18);
  --shadow-md:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 2px 4px -1px hsl(330 70% 30% / 0.18);
  --shadow-lg:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 4px 6px -1px hsl(330 70% 30% / 0.18);
  --shadow-xl:
    0px 3px 0px 0px hsl(330 70% 30% / 0.18),
    0px 8px 10px -1px hsl(330 70% 30% / 0.18);
  --shadow-2xl: 0px 3px 0px 0px hsl(330 70% 30% / 0.45);
  --tracking-normal: 0em;
}

